import{_ as a,o as r,c as t,a2 as o}from"./chunks/framework.BS0bAV7E.js";const p=JSON.parse('{"title":"Crash recovery architecture","description":"","frontmatter":{},"headers":[],"relativePath":"arch/crash-recovery.md","filePath":"arch/crash-recovery.md"}'),c={name:"arch/crash-recovery.md"};function h(s,e,i,n,l,d){return r(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="crash-recovery-architecture" tabindex="-1">Crash recovery architecture <a class="header-anchor" href="#crash-recovery-architecture" aria-label="Permalink to &quot;Crash recovery architecture&quot;">​</a></h1><h2 id="the-crash-path" tabindex="-1">The crash path <a class="header-anchor" href="#the-crash-path" aria-label="Permalink to &quot;The crash path&quot;">​</a></h2><p><code>kernel/core/core_crash.c</code>: an unhandled exception captures the frame (registers, vector, fault address, CR2/CR3 context), prints the dump to serial, writes a crashlog record to the /etc volume, and halts. <code>dumpinfo</code> reads the record back after reboot; <code>crashlog</code> lists the history.</p><h2 id="panic-grade-isolation" tabindex="-1">Panic-grade isolation <a class="header-anchor" href="#panic-grade-isolation" aria-label="Permalink to &quot;Panic-grade isolation&quot;">​</a></h2><ul><li>IST1 gives #DF/#MC their own stack - a double fault during a fault handler still has somewhere to run.</li><li>The exception-exit path never context-switches on IST2 (BUG-0139).</li><li>The boot self-test (#DE/#UD/#PF caught, kernel alive) runs BEFORE the shell - the machinery is proven before anything trusts it.</li></ul><h2 id="the-recovery-posture" tabindex="-1">The recovery posture <a class="header-anchor" href="#the-recovery-posture" aria-label="Permalink to &quot;The recovery posture&quot;">​</a></h2><p>The system is its own WinRE: boot from ISO with no disk, inspect a sick machine&#39;s volumes, fix configs, re-install boot code (<code>install</code>/<code>abdisk</code>/<code>grub-install</code> carry their payload inside the kernel), pull logs and dumps off /etc. The recovery manual with the rescue table: <a href="./../manual/recovery.html">../manual/recovery.md</a>.</p><h2 id="testing" tabindex="-1">Testing <a class="header-anchor" href="#testing" aria-label="Permalink to &quot;Testing&quot;">​</a></h2><p><code>crashtest</code> (deliberate panic), <code>dumpinfo</code> (read-back), the regression battery&#39;s crashlog check, and the E2E hard-reset scenarios (S12/S13) which prove the <em>reboot</em> half of the story through the hardware watchdogs.</p>',9)])])}const m=a(c,[["render",h]]);export{p as __pageData,m as default};
